// Opening film, ported from the original wedding-site.html.
// Self-contained web component: shadow DOM scopes the original CSS, and the
// original calendar / scenery / cue timings run here, tightened to ~55%.
// Fires a bubbling "filmdone" event when the guest opens it, skips, or it ends.
const CSS = "\n:host{\n  color-scheme:light only;\n  --paper:#F7F4ED; --ink:#26332A; --ink-soft:#767B70;\n  --peri:#3E5741; --peri-dark:#26332A; --butter:#B08D3E; --gold-soft:#D9C9A3;\n  --night:#212B24; --line:#E2DCCC; --hair:#D8D1BF; --card:#FFFFFF;\n  --radius:2px;\n}\n*{box-sizing:border-box;margin:0;padding:0}\nhtml{scroll-behavior:smooth;background:#F7F4ED;color-scheme:light only;-webkit-text-size-adjust:100%}\n@media(prefers-color-scheme:dark){html,body{background:#F7F4ED;color:#26332A}}\nbody{background:var(--paper);color:var(--ink);font-family:'Karla',sans-serif;font-size:16.5px;line-height:1.75;-webkit-font-smoothing:antialiased}\nh1,h2,h3{font-family:'Cormorant Garamond',serif;line-height:1.2;font-weight:500}\nh2{font-size:clamp(30px,4.6vw,46px);margin-bottom:10px;letter-spacing:.2px}\nh3{font-size:21px;letter-spacing:.2px}\n.eyebrow{font-size:10.5px;letter-spacing:3.4px;text-transform:uppercase;color:var(--butter);font-weight:500;margin-bottom:14px;font-family:'Karla',sans-serif}\nsection{padding:100px 24px;max-width:900px;margin:0 auto}\n.rule{width:44px;height:1px;background:var(--butter);margin:22px 0}\n.rule.mid{margin-left:auto;margin-right:auto}\n\n.btn{display:inline-block;border:1px solid var(--butter);background:var(--butter);color:#FFFDF8;font-family:'Karla',sans-serif;font-weight:500;font-size:11.5px;letter-spacing:2.4px;text-transform:uppercase;padding:15px 32px;border-radius:var(--radius);cursor:pointer;text-decoration:none;transition:background 0.2s,color 0.2s,border-color 0.2s}\n.btn:hover{background:transparent;color:var(--butter)}\n.btn.ghost{background:transparent;color:var(--ink);border-color:var(--hair)}\n.btn.ghost:hover{border-color:var(--ink);color:var(--ink)}\n.btn.peri{background:var(--peri);border-color:var(--peri);color:#FFFDF8}\n.btn.peri:hover{background:transparent;color:var(--peri)}\n\ninput,select,textarea{width:100%;font-family:'Karla',sans-serif;font-size:16px;padding:13px 0;border:none;border-bottom:1px solid var(--hair);border-radius:0;background:transparent;color:var(--ink);transition:border-color 0.2s}\ninput:focus,select:focus,textarea:focus{outline:none;border-bottom-color:var(--butter)}\nselect{padding-left:0}\ntextarea{border:1px solid var(--hair);padding:13px 14px;resize:vertical}\nlabel{font-weight:500;font-size:11px;letter-spacing:1.8px;text-transform:uppercase;color:var(--ink-soft);display:block;margin:26px 0 2px}\n.card{background:var(--card);border:1px solid var(--line);border-radius:var(--radius);padding:34px 30px}\n.muted{color:var(--ink-soft)}\n.hidden{display:none!important}\n\n.card-list{list-style:none;margin:14px 0 0;padding:0}\n.card-list li{border-top:1px solid var(--hair);padding:11px 0;font-size:14.5px;line-height:1.5}\n.card-list li:first-child{border-top:none}\n.card-list b{font-weight:500;display:block;font-family:'Cormorant Garamond',serif;font-size:17px}\n.card-list span{color:var(--ink-soft);font-size:13px}\n.card-list a{color:var(--butter);text-decoration:none;white-space:nowrap}\n.card-list a:hover{border-bottom:1px solid var(--butter)}\n/* keep the heavier film layers on their own compositor layer */\n#phaseCal,#phaseMap,.scene,.inside{contain:paint}\n.aisle-walk{will-change:transform}\n.map-layer{will-change:transform,opacity}\n@media(max-width:520px){\n  .petal:nth-child(n+9){display:none}\n}\n\n/* monogram crest */\n.crest{width:118px;margin:0 auto 6px;display:block}\n.crest text{letter-spacing:1px}\n\n/* ------------------------------------------------------------\n   Force-dark immunity: WebView auto-dark inverts background\n   COLOURS but leaves background IMAGES alone, so every surface\n   is painted with a flat gradient instead of a colour.\n   ------------------------------------------------------------ */\nhtml{background-color:#F7F4ED!important;background-image:linear-gradient(#F7F4ED,#F7F4ED)!important}\nbody{background-color:#F7F4ED!important;background-image:linear-gradient(#F7F4ED,#F7F4ED)!important;color:#26332A!important}\n#pageBg{position:fixed;inset:0;background-image:linear-gradient(#F7F4ED,#F7F4ED);z-index:-2;pointer-events:none}\n.card{background-image:linear-gradient(#FFFFFF,#FFFFFF)!important}\nnav{background-image:linear-gradient(rgba(247,244,237,.95),rgba(247,244,237,.95))!important}\n.ticket{background-image:linear-gradient(#FFFFFF,#FFFFFF)!important}\n.btn{background-image:linear-gradient(#B08D3E,#B08D3E)}\n.btn.ghost{background-image:none}\n.btn.peri{background-image:linear-gradient(#3E5741,#3E5741)}\n.choice button.on{background-image:linear-gradient(#3E5741,#3E5741)}\n@media(prefers-color-scheme:dark){\n  html,body{background-image:linear-gradient(#F7F4ED,#F7F4ED)!important;color:#26332A!important}\n  h1,h2,h3,summary,strong{color:#26332A!important}\n  .lineup .act b{color:#26332A!important}\n  .cal-grid b{color:#26332A!important}\n  .cal-grid b.mute{color:transparent!important}\n  .muted,label,.stat span,.cal-year{color:#767B70!important}\n  .eyebrow,.lineup time,.btn.ghost:hover{color:#B08D3E!important}\n  input,select,textarea{color:#26332A!important;background-image:none!important}\n  nav a{color:#767B70!important}\n  nav a.pill{color:#B08D3E!important}\n}\n\n/* tipi watermark, carried behind the page */\n#watermark{position:fixed;right:-6vw;bottom:-4vh;width:min(680px,88vw);z-index:0;opacity:.05;pointer-events:none;user-select:none}\n#watermark svg{width:100%;display:block}\nnav,section,footer,#gate,#adminGate{position:relative;z-index:1}\n.ornament{display:flex;align-items:center;gap:14px;margin:22px 0}\n.ornament.mid{justify-content:center}\n.ornament::before,.ornament::after{content:\"\";height:1px;background:var(--hair);flex:0 0 46px}\n.ornament.mid::before,.ornament.mid::after{flex:0 0 60px}\n.ornament svg{width:18px;height:18px;display:block;opacity:.85}\n\n\n/* ============================================================\n   Opening film: the date, the place, the walk down the aisle\n   ============================================================ */\n#envelope{position:fixed;inset:0;background-image:linear-gradient(#EFEBE0,#EFEBE0);z-index:110;overflow:hidden;transition:opacity 1.28s ease}\n#envelope.gone{opacity:0;pointer-events:none}\n\n/* ---------- phase 1: the calendar ---------- */\n#phaseCal{position:absolute;inset:0;display:flex;align-items:center;justify-content:center;background-image:linear-gradient(#F3F0E7,#EDE9DE);opacity:0;animation:calIn 0.64s ease 0.08s forwards,calOut 1.36s cubic-bezier(.5,0,.72,1) 3.44s forwards}\n@keyframes calIn{to{opacity:1}}\n@keyframes calOut{0%{opacity:1;transform:scale(1)}40%{opacity:1}100%{opacity:0;transform:scale(16)}}\n.cal-stack{position:relative;width:min(352px,84vw);aspect-ratio:.84;perspective:1500px}\n.cal-page{position:absolute;inset:0;background-image:linear-gradient(#FFFFFF,#FDFCF8);border:1px solid var(--line);padding:22px 20px 16px;transform-origin:50% 0%;backface-visibility:hidden;box-shadow:0 16px 38px rgba(38,51,42,.11);transition:transform 0.48s cubic-bezier(.42,.06,.4,1),opacity 0.48s,box-shadow 0.48s}\n.cal-page.turned{transform:rotateX(-118deg);opacity:0;box-shadow:0 0 0 rgba(0,0,0,0)}\n.cal-sprig{position:absolute;top:12px;right:14px;width:36px;opacity:.75}\n.cal-head{text-align:center;font-family:'Cormorant Garamond',serif;font-size:21px;letter-spacing:2.4px;margin-bottom:1px}\n.cal-year{text-align:center;font-size:9px;letter-spacing:3.6px;color:var(--ink-soft);margin-bottom:14px}\n.cal-dow{display:grid;grid-template-columns:repeat(7,1fr);margin-bottom:5px}\n.cal-dow span{text-align:center;font-size:7.5px;letter-spacing:1px;color:var(--ink-soft)}\n.cal-grid{display:grid;grid-template-columns:repeat(7,1fr);gap:1px}\n.cal-grid b{aspect-ratio:1;display:flex;align-items:center;justify-content:center;font-family:'Cormorant Garamond',serif;font-size:14.5px;font-weight:400;color:var(--ink)}\n.cal-grid b.mute{color:transparent}\n.cal-foot{text-align:center;margin-top:10px;font-family:'Cormorant Garamond',serif;font-style:italic;font-size:15px;color:var(--butter);opacity:0;transition:opacity 0.72s}\n.cal-foot.on{opacity:1}\n#penRing{position:absolute;inset:0;pointer-events:none;overflow:visible;z-index:9}\n#penRing path{fill:none;stroke:#B4302A;stroke-linecap:round;opacity:.9;\n  stroke-dasharray:var(--len,400);stroke-dashoffset:var(--len,400);transition:stroke-dashoffset 0.88s cubic-bezier(.45,.1,.7,1)}\n#penRing.drawn path{stroke-dashoffset:0}\n\n/* ---------- phase 2: the map, three stages inwards ---------- */\n#phaseMap{position:absolute;inset:0;overflow:hidden;background-image:linear-gradient(#DCE6EA,#D2DEE3);opacity:0;animation:mapIn 0.88s ease 3.76s forwards,mapOut 1.04s ease 13.12s forwards}\n@keyframes mapIn{to{opacity:1}}\n@keyframes mapOut{to{opacity:0}}\n.map-layer{position:absolute;left:50%;top:50%;opacity:0}\n.mapA{width:max(100vw,66vh)}\n.mapB,.mapC{width:max(100vw,100vh)}\n.map-layer svg{width:100%;display:block}\n.mapA{transform-origin:66.6% 61.5%;animation:mapAz 2.24s cubic-bezier(.4,.06,.6,1) 4.32s forwards,layFade 0.88s ease 4.32s forwards,layOut 0.72s ease 6.24s forwards}\n@keyframes mapAz{0%{transform:translate(-66.6%,-61.5%) scale(1)}100%{transform:translate(-66.6%,-61.5%) scale(2.1)}}\n.mapB{transform-origin:50% 50%;animation:mapBz 2.4s cubic-bezier(.42,.06,.6,1) 6.08s forwards,layFade 0.88s ease 6.08s forwards,layOut 0.72s ease 8.32s forwards}\n@keyframes mapBz{0%{transform:translate(-50%,-50%) scale(1)}100%{transform:translate(-50%,-50%) scale(1.7)}}\n.mapC{transform-origin:50% 50%;animation:mapCz 3.52s cubic-bezier(.44,.06,.6,1) 8.16s forwards,layFade 0.88s ease 8.16s forwards}\n@keyframes mapCz{0%{transform:translate(-50%,-50%) scale(1)}100%{transform:translate(-50%,-50%) scale(1.6)}}\n@keyframes layFade{to{opacity:1}}\n@keyframes layOut{to{opacity:0}}\n.map-lbl{position:absolute;left:0;right:0;text-align:center;font-family:'Karla',sans-serif;letter-spacing:4.4px;text-transform:uppercase;color:#5E6B5C;font-size:11px;opacity:0}\n.map-lbl.l1{top:8%;animation:lblCycle 1.76s ease 4.32s forwards}\n.map-lbl.l2{top:8%;animation:lblCycle 1.76s ease 6.08s forwards}\n.map-lbl.l3{top:8%;animation:lblCycle 2.88s ease 8.32s forwards}\n@keyframes lblCycle{0%{opacity:0}22%{opacity:.85}72%{opacity:.85}100%{opacity:0}}\n.map-pin{position:absolute;left:50%;top:50%;transform:translate(-50%,-100%) scale(.8);opacity:0;animation:pinIn 1.12s cubic-bezier(.2,.8,.3,1.3) 8.96s forwards;z-index:4}\n@keyframes pinIn{to{opacity:1;transform:translate(-50%,-100%) scale(1)}}\n.map-pin svg{width:42px;display:block;margin:0 auto;filter:drop-shadow(0 5px 9px rgba(0,0,0,.3))}\n.map-pin p{font-family:'Cormorant Garamond',serif;font-size:20px;color:#2F4433;margin-top:7px;white-space:nowrap;text-align:center}\n.map-pin span{display:block;font-family:'Karla',sans-serif;font-size:8.5px;letter-spacing:3px;color:#6E7A6C;margin-top:3px}\n.pin-halo{position:absolute;left:50%;top:50%;width:16px;height:16px;margin:-8px 0 0 -8px;border-radius:50%;border:2px solid rgba(176,141,62,.75);opacity:0;animation:halo 1.76s ease-out 9.12s infinite;z-index:3}\n@keyframes halo{0%{opacity:.7;transform:scale(1)}100%{opacity:0;transform:scale(6)}}\n\n/* ---------- phase 3: the grounds, camera panning ---------- */\n.scene{position:absolute;inset:0;overflow:hidden;opacity:0;animation:sceneIn 1.2s ease 13.04s forwards}\n@keyframes sceneIn{to{opacity:1}}\n.sky{position:absolute;inset:0;background-image:linear-gradient(#B7CFDC 0%,#D3E2E4 46%,#EAF0E6 74%,#DFE6D2 100%)}\n.sun{position:absolute;top:18%;left:11%;width:56px;height:56px;border-radius:50%;background-image:radial-gradient(circle,#FFF8E2 30%,rgba(255,244,208,.5) 60%,transparent 72%);box-shadow:0 0 90px 40px rgba(255,246,214,.4)}\n.cloud{position:absolute;background-image:linear-gradient(rgba(255,255,255,.74),rgba(255,255,255,.74));border-radius:50%;filter:blur(1px)}\n.skypan{position:absolute;inset:0;animation:none}\n@keyframes skyPan{0%{transform:translateX(-6%)}40%{transform:translateX(0)}100%{transform:translateX(3%)}}\n\n/* the world the camera moves through */\n.world{position:absolute;left:-50%;top:0;width:200%;height:100%;transform-origin:55.5% 70%;\n  animation:cameraMove 6.72s cubic-bezier(.42,.04,.58,1) 13.04s both}\n@keyframes cameraMove{\n  0%{opacity:0;transform:translate(-5.5%,0) scale(.97)}\n  8%{opacity:1;transform:translate(-5.5%,0) scale(1)}\n  20%{opacity:1;transform:translate(-5.5%,0) scale(1)}\n  44%{opacity:1;transform:translate(-5.5%,-5%) scale(1.85)}\n  58%{opacity:1;transform:translate(-5.5%,-6%) scale(1.95)}\n  78%{opacity:1;transform:translate(-5.5%,-15%) scale(3.6)}\n  100%{opacity:0;transform:translate(-5.5%,-26%) scale(13)}\n}\n}\n}\n}\n.hills{position:absolute;left:0;right:0;bottom:30%;height:30%;background-image:radial-gradient(ellipse at 12% 100%,#9DAF89 62%,transparent 64%),radial-gradient(ellipse at 40% 100%,#93A67F 60%,transparent 62%),radial-gradient(ellipse at 68% 100%,#A3B490 58%,transparent 60%),radial-gradient(ellipse at 92% 100%,#96A882 60%,transparent 62%)}\n.treeline{position:absolute;left:-4%;right:-4%;bottom:31%;height:13%;background-image:radial-gradient(ellipse at 6% 100%,#6E8460 60%,transparent 62%),radial-gradient(ellipse at 18% 100%,#637956 58%,transparent 60%),radial-gradient(ellipse at 30% 100%,#6E8460 62%,transparent 64%),radial-gradient(ellipse at 44% 100%,#5D7351 58%,transparent 60%),radial-gradient(ellipse at 58% 100%,#6E8460 60%,transparent 62%),radial-gradient(ellipse at 72% 100%,#637956 58%,transparent 60%),radial-gradient(ellipse at 86% 100%,#6E8460 62%,transparent 64%),radial-gradient(ellipse at 97% 100%,#5D7351 58%,transparent 60%)}\n.fields{position:absolute;left:0;right:0;bottom:0;height:33%;background-image:linear-gradient(#AFC08E,#93A673)}\n.hedge-line{position:absolute;left:0;right:0;height:3px;background-image:linear-gradient(#5F7350,#5F7350);opacity:.5}\n.w-item{position:absolute;bottom:16%;transform:translateX(-50%)}\n.w-tipi{left:62%;width:46%;bottom:27%}\n\n/* the door drapes, drawn back as we arrive */\n.drape-l,.drape-r{transform-box:fill-box;transform-origin:50% 0%}\n.drape-l{animation:drapeL 1.52s cubic-bezier(.32,.06,.38,1) 16s both}\n.drape-r{animation:drapeR 1.52s cubic-bezier(.32,.06,.38,1) 16s both}\n@keyframes drapeL{0%{transform:translateX(0) rotate(0deg) scaleX(1)}100%{transform:translateX(-40%) rotate(-14deg) scaleX(.58)}}\n@keyframes drapeR{0%{transform:translateX(0) rotate(0deg) scaleX(1)}100%{transform:translateX(40%) rotate(14deg) scaleX(.58)}}\n.tieback{opacity:0;animation:layFade 0.8s ease 17.12s both}\n\n/* petals through the daylight */\n.petal{position:absolute;width:9px;height:7px;border-radius:60% 40% 55% 45%;opacity:0;will-change:transform;animation:petalFall linear infinite;z-index:3}\n@keyframes petalFall{\n  0%{opacity:0;transform:translate(0,-8vh) rotate(0deg)}\n  8%{opacity:.85}\n  50%{transform:translate(26px,42vh) rotate(180deg)}\n  92%{opacity:.7}\n  100%{opacity:0;transform:translate(-14px,96vh) rotate(360deg)}\n}\n\n/* ---------- phase 4: down the aisle ---------- */\n.inside{position:absolute;inset:0;overflow:hidden;opacity:0;background-image:linear-gradient(#EFE7D6 0%,#E9DFC8 46%,#BCAA88 46%,#B09E7C 100%);animation:sceneIn 1.52s ease 19.44s forwards}\n.aisle-walk{position:absolute;inset:0;transform-origin:50% 44.4%;animation:walk 5.44s cubic-bezier(.31,.02,.47,1) 19.76s forwards}\n@keyframes walk{0%{transform:scale(1)}100%{transform:scale(2.4)}}\n.aisle-bob{position:absolute;inset:0;animation:bob 2s ease-in-out 19.76s 3 both}\n@keyframes bob{0%,100%{transform:translateY(0)}25%{transform:translateY(-.4%)}75%{transform:translateY(.3%)}}\n.aisle-scene{position:absolute;inset:0}\n.bulb{animation:bulbGlow 3.36s ease-in-out infinite}\n@keyframes bulbGlow{0%,100%{opacity:.62}50%{opacity:1}}\n\n/* the invitation, in its envelope on the easel */\n.env-wrap{position:absolute;left:50%;bottom:12%;width:min(390px,89.5vw);z-index:6;opacity:0;text-align:center;\n  transform:translate(-50%,-93%) scale(.15);transform-origin:50% 100%;\n  animation:inviteGrow 5.44s cubic-bezier(.31,.02,.47,1) 19.76s forwards,layFade 1.28s ease 19.92s forwards}\n@keyframes inviteGrow{to{transform:translate(-50%,0) scale(1)}}\n.envelope{position:relative;z-index:2;width:100%;aspect-ratio:.92;perspective:1100px}\n.env-shell,.env-lid{position:absolute;inset:0;width:100%;height:100%;display:block}\n.env-shell{z-index:3;filter:drop-shadow(0 22px 34px rgba(60,50,24,.34))}\n.env-lid{z-index:4;transform-origin:50% 0;transition:transform 1.84s cubic-bezier(.6,-.08,.36,1.06)}\n.env-open .env-lid{transform:rotateX(-168deg)}\n.seal{position:absolute;left:50%;top:50%;width:16%;aspect-ratio:1;transform:translate(-50%,-50%);\n  border-radius:50%;background-image:radial-gradient(circle at 34% 28%,#C9A657,#8A6C29 72%);\n  border:1px solid #6E5520;box-shadow:0 2px 8px rgba(0,0,0,.32);display:flex;align-items:center;\n  justify-content:center;font-family:'Cormorant Garamond',serif;color:#2E240A;font-size:3.6vmin;\n  letter-spacing:.5px;z-index:5;transition:transform 0.88s cubic-bezier(.3,-.5,.6,1.4),opacity 0.8s}\n.env-open .seal{transform:translate(-50%,-50%) scale(.28) rotate(34deg);opacity:0}\n\n/* the card, drawn up out of the envelope */\n.env-card{position:absolute;left:3%;width:94%;bottom:5%;aspect-ratio:.70;z-index:9;\n  display:flex;flex-direction:column;justify-content:center;\n  background-image:linear-gradient(#FFFFFF,#FFFDF9);border:1px solid #E4DECE;\n  padding:38px 22px;box-shadow:0 24px 48px rgba(60,50,24,.32);\n  opacity:0;transform:translateY(12%) scale(.97);transform-origin:50% 50%;\n  transition:transform 2.08s cubic-bezier(.22,.72,.28,1) 0.36s,opacity 1.28s ease 0.44s}\n.env-open .env-card{opacity:1;transform:translateY(-14%) scale(1)}\n.env-sprig{width:52px;margin:0 auto 14px;display:block;opacity:0;transition:opacity 0.96s ease 1.28s}\n.env-open .env-sprig{opacity:.9}\n.env-card .ln{opacity:0;transform:translateY(7px);transition:opacity 0.8s ease,transform 0.8s ease}\n.env-open .env-card .ln{opacity:1;transform:translateY(0)}\n.env-open .ln1{transition-delay:1.52s}\n.env-open .ln2{transition-delay:1.92s}\n.env-open .ln3{transition-delay:2.4s}\n.env-open .ln4{transition-delay:2.88s}\n.env-card .to{font-size:9px;letter-spacing:2.8px;text-transform:uppercase;color:var(--ink-soft)}\n.env-card h2{font-size:clamp(23px,6.2vw,32px);margin:14px 0 2px;font-weight:400}\n.env-card h2 em{color:var(--butter);font-style:italic}\n.env-rule{width:36px;height:1px;background-image:linear-gradient(#B08D3E,#B08D3E);margin:14px auto}\n.env-date{font-family:'Cormorant Garamond',serif;font-size:18px;letter-spacing:.6px}\n.env-venue{font-family:'Cormorant Garamond',serif;font-size:15px;color:var(--ink-soft);line-height:1.5;margin-top:3px}\n.env-guest{font-family:'Cormorant Garamond',serif;font-style:italic;font-size:18px;margin-top:18px}\n.env-stand{position:absolute;left:50%;bottom:-8%;width:64%;transform:translateX(-50%);z-index:1}\n.env-stand svg{width:100%;display:block}\n#envBtn{position:absolute;left:50%;bottom:7%;transform:translateX(-50%) translateY(7px);opacity:0;\n  transition:opacity 0.96s ease,transform 0.96s ease;z-index:12}\n#envBtn.on{opacity:1;transform:translateX(-50%) translateY(0)}\n.env-skip{position:absolute;bottom:24px;right:20px;background-image:linear-gradient(rgba(255,253,248,.72),rgba(255,253,248,.72));\n  border:1px solid rgba(38,51,42,.22);color:rgba(38,51,42,.72);border-radius:999px;\n  font-family:'Karla',sans-serif;font-size:10px;letter-spacing:2px;text-transform:uppercase;\n  padding:9px 18px;cursor:pointer;z-index:13;opacity:0;transition:opacity 0.72s,color 0.2s,border-color 0.2s}\n.env-skip.show{opacity:1}\n.env-skip:hover{color:#26332A;border-color:rgba(38,51,42,.5)}\n.env-skip:focus-visible{outline:2px solid var(--butter);outline-offset:3px}\n.replay{background:none;border:none;padding:0;margin-top:18px;cursor:pointer;color:var(--ink-soft);\n  font-family:'Karla',sans-serif;font-size:10px;letter-spacing:2.2px;text-transform:uppercase;\n  border-bottom:1px solid var(--hair);transition:color 0.2s,border-color 0.2s}\n.replay:hover{color:var(--butter);border-color:var(--butter)}\na:focus-visible,button:focus-visible,summary:focus-visible{outline:2px solid var(--butter);outline-offset:3px;border-radius:2px}\n\n\n@media(prefers-reduced-motion:reduce){\n  #phaseCal,#phaseMap,.map-layer,.map-lbl,.map-pin,.scene,.world,.skypan,.inside,.aisle-walk,.env-wrap{animation-duration:0.32s!important;animation-delay:0s!important}\n  .env-wrap{transform:translate(-50%,0) scale(1)!important}\n  .env-card{z-index:9!important}\n  .aisle-bob,.petal,.pin-halo,.bulb,.drape-l,.drape-r{animation:none!important}\n  .cal-page,.env-lid,.seal,.env-card,.env-card .ln,.env-sprig,#penRing path{transition-duration:0.32s!important;transition-delay:0s!important}\n}\n\n/* ============================================================\n   RSVP wizard — one question at a time, then into the site\n   ============================================================ */\n#wizard{position:fixed;inset:0;z-index:100;background-image:linear-gradient(#F7F4ED,#F2EEE3);\n  display:flex;align-items:center;justify-content:center;padding:20px;overflow-y:auto;\n  opacity:0;transition:opacity 0.56s ease}\n#wizard.on{opacity:1}\n#wizard.leaving{opacity:0;pointer-events:none}\n.wiz-card{width:100%;max-width:440px;background-image:linear-gradient(#FFFFFF,#FFFFFF);\n  border:1px solid var(--line);padding:30px 26px 26px;position:relative}\n.wiz-top{margin-bottom:24px}\n.wiz-count{font-size:9.5px;letter-spacing:2.6px;text-transform:uppercase;color:var(--ink-soft)}\n.wiz-bar{height:1px;background-image:linear-gradient(var(--hair),var(--hair));margin-top:10px}\n.wiz-bar i{display:block;height:1px;width:0;background-image:linear-gradient(var(--butter),var(--butter));\n  transition:width 0.4s cubic-bezier(.3,.7,.3,1)}\n.wiz-body h3{font-size:26px;font-weight:400;margin-bottom:6px}\n.wiz-body .lead{color:var(--ink-soft);font-size:14.5px;margin-bottom:22px;line-height:1.6}\n.wiz-guest{border-top:1px solid var(--hair);padding-top:18px;margin-top:18px}\n.wiz-guest:first-child{border-top:none;padding-top:0;margin-top:0}\n.wiz-guest .nm{font-family:'Cormorant Garamond',serif;font-size:20px;margin-bottom:10px}\n.wiz-pick{display:flex;gap:8px}\n.wiz-pick button{flex:1;border:1px solid var(--hair);background:none;border-radius:2px;\n  font-family:'Cormorant Garamond',serif;font-size:15.5px;padding:13px 8px;cursor:pointer;\n  color:var(--ink-soft);transition:all 0.16s}\n.wiz-pick button:hover{border-color:var(--butter);color:var(--ink)}\n.wiz-pick button.on{background-image:linear-gradient(#3E5741,#3E5741);border-color:#3E5741;color:#FFFDF8}\n.wiz-field{margin-top:16px}\n.wiz-field label{margin-top:0}\n.wiz-err{color:#9E4A3A;font-size:13px;margin-top:14px;min-height:18px}\n.wiz-foot{display:flex;gap:10px;margin-top:28px}\n.wiz-foot .btn{flex:1}\n.wiz-foot .btn.ghost{flex:0 0 34%}\n.wiz-later{display:block;margin:18px auto 0;background:none;border:none;cursor:pointer;\n  color:var(--ink-soft);font-family:'Karla',sans-serif;font-size:10px;letter-spacing:2px;\n  text-transform:uppercase;border-bottom:1px solid var(--hair);padding-bottom:2px}\n.wiz-later:hover{color:var(--butter);border-color:var(--butter)}\n.wiz-review{border-top:1px solid var(--hair);padding:14px 0;display:flex;justify-content:space-between;gap:14px;font-size:14.5px}\n.wiz-review span{color:var(--ink-soft);flex:0 0 38%}\n.wiz-review b{font-weight:400;text-align:right}\n.wiz-done{text-align:center}\n.wiz-done .tick{width:54px;height:54px;margin:0 auto 18px;border-radius:50%;\n  border:1px solid var(--butter);display:flex;align-items:center;justify-content:center;\n  font-family:'Cormorant Garamond',serif;font-size:26px;color:var(--butter)}\n@media(max-width:420px){.wiz-card{padding:26px 20px 22px}.wiz-body h3{font-size:23px}}\n\n/* gate */\n#gate{position:fixed;inset:0;background:var(--paper);z-index:100;display:flex;align-items:center;justify-content:center;padding:20px}\n#gate .card{max-width:400px;width:100%;text-align:center;padding:44px 34px}\n#gate .card h2{font-size:32px}\n\n/* nav */\nnav{position:sticky;top:0;background:rgba(247,244,237,.94);backdrop-filter:blur(10px);border-bottom:1px solid var(--hair);z-index:50;display:flex;justify-content:space-between;align-items:center;padding:18px 26px}\nnav .logo{font-family:'Cormorant Garamond',serif;font-size:19px;letter-spacing:3px}\nnav .links{display:flex;gap:26px;align-items:center;font-size:11px;letter-spacing:1.6px;text-transform:uppercase;font-weight:500}\nnav a{color:var(--ink-soft);text-decoration:none;transition:color 0.16s}\nnav a:hover{color:var(--ink)}\nnav a.pill{color:var(--butter)}\n@media(max-width:640px){nav .links a:not(.pill){display:none}}\n\n/* hero */\n#hero{text-align:center;padding:110px 24px 90px;position:relative;overflow:hidden}\n#hero h1{font-size:clamp(46px,9vw,92px);font-weight:400;letter-spacing:.5px}\n#hero h1 .amp{color:var(--butter);font-style:italic;font-weight:400}\n#hero .date-line{font-family:'Cormorant Garamond',serif;font-size:22px;margin:22px 0 4px;letter-spacing:.4px}\n#hero .venue-line{color:var(--ink-soft);font-size:14px;letter-spacing:.4px;margin-bottom:34px}\n.countdown{display:flex;justify-content:center;margin:38px 0 34px}\n.countdown div{padding:0 22px;min-width:74px;border-right:1px solid var(--hair)}\n.countdown div:last-child{border-right:none}\n.countdown b{font-family:'Cormorant Garamond',serif;font-size:34px;font-weight:400;display:block;line-height:1.1}\n.countdown span{font-size:9.5px;letter-spacing:2.2px;text-transform:uppercase;color:var(--ink-soft)}\n.hero-actions{display:flex;gap:14px;justify-content:center;flex-wrap:wrap}\n@media(prefers-reduced-motion:reduce){html{scroll-behavior:auto}}\n\n/* order of the day */\n.lineup{border-top:1px solid var(--hair)}\n.lineup .row{display:flex;gap:30px;padding:26px 2px;border-bottom:1px solid var(--hair);align-items:baseline}\n.lineup time{font-family:'Cormorant Garamond',serif;font-size:19px;color:var(--butter);min-width:78px;letter-spacing:.5px}\n.lineup .act b{font-family:'Cormorant Garamond',serif;font-size:21px;font-weight:500;display:block;margin-bottom:2px}\n.lineup .act p{font-size:15px;color:var(--ink-soft);line-height:1.6}\n@media(max-width:560px){.lineup .row{flex-direction:column;gap:6px}}\n\n/* grids */\n.grid2{display:grid;grid-template-columns:repeat(auto-fit,minmax(280px,1fr));gap:1px;margin-top:34px;background:var(--hair);border:1px solid var(--hair)}\n.grid2 .card{border:none;border-radius:0}\n\n/* faq */\ndetails{border-bottom:1px solid var(--hair)}\ndetails:first-of-type{border-top:1px solid var(--hair)}\nsummary{cursor:pointer;font-family:'Cormorant Garamond',serif;font-size:19px;padding:22px 2px;list-style:none;display:flex;justify-content:space-between;gap:20px;align-items:baseline}\nsummary::-webkit-details-marker{display:none}\nsummary::after{content:\"+\";font-size:19px;color:var(--butter);font-weight:400}\ndetails[open] summary::after{content:\"\\2013\"}\ndetails p{padding:0 2px 24px;color:var(--ink-soft);max-width:64ch}\n\n\n\n\n/* admin */\n#adminPanel table{width:100%;border-collapse:collapse;font-size:14px;margin-top:14px}\n#adminPanel th{font-size:10px;letter-spacing:1.6px;text-transform:uppercase;color:var(--ink-soft);font-weight:500}\n#adminPanel th,#adminPanel td{border-bottom:1px solid var(--hair);padding:11px 8px;text-align:left;vertical-align:top}\n\nfooter{text-align:center;padding:70px 24px;color:var(--ink-soft);font-size:13px;border-top:1px solid var(--hair);max-width:900px;margin:0 auto}\nfooter .mono{font-family:'Cormorant Garamond',serif;font-size:17px;letter-spacing:3px;color:var(--ink);margin-bottom:10px}\n.demo-banner{background:var(--butter);border-bottom:2px solid var(--ink);text-align:center;font-size:13px;font-weight:700;padding:6px}\n";
